package ma.projet.util; import ma.projet.beans.*; import org.hibernate.*; import org.hibernate.cfg.Configuration; import java.util.Properties; public final class HibernateUtil {private static SessionFactory sf=build(); private static SessionFactory build(){try{Properties p=new Properties();try(var i=HibernateUtil.class.getClassLoader().getResourceAsStream("application.properties")){p.load(i);}return new Configuration().addAnnotatedClass(Personne.class).addAnnotatedClass(Homme.class).addAnnotatedClass(Femme.class).addAnnotatedClass(Mariage.class).addProperties(p).buildSessionFactory();}catch(Exception e){throw new ExceptionInInitializerError(e);}} public static SessionFactory getSessionFactory(){return sf;} public static void shutdown(){sf.close();}}
